/* Educational geometry: not a vendor machine, TSMC layout, scale model, or process recipe. */
export function costBuilders({THREE,world,box,group,explode,pipe,ring,textLabel,floor,mat,palette:p}){
 const cylinder=(parent,r,h,x,y,z,color,open=false)=>{const m=new THREE.Mesh(new THREE.CylinderGeometry(r,r,h,48,1,open),mat(color));m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m};
 const wafer=(parent,x,y,z,r=1.3)=>{cylinder(parent,r,.06,x,y,z,0x8a96cf);for(let a=-r+.2;a<r;a+=.25)for(let b=-r+.2;b<r;b+=.25)if(Math.hypot(Math.abs(a)+.1,Math.abs(b)+.1)<r)box(parent,.21,.006,.21,x+a,y+.035,z+b,0x6080b2)};
 function fabflow(){floor(11);const raw=group(world,'raw');wafer(raw,-2.45,.35,0,2.15);textLabel(raw,'WAFER',-2.5,.72,2.35,1.8);explode(raw,-.4,0,0);
 const base=group(world,'flow');box(base,3.4,.25,3.2,1.65,.4,0,p.case);textLabel(base,'FEOL / TRANSISTORS',2.0,.6,1.9,2.8);
 const ns=group(world,'nanosheet');for(let x=0;x<3;x++){const gx=.55+x*1.05;box(ns,.7,.65,1.7,gx,.88,0,p.green);box(ns,.54,.73,.58,gx,1,0,p.gold);for(let i=0;i<3;i++)box(ns,.66,.065,1.7,gx,.84+i*.18,0,0x79b6e0)}textLabel(ns,'GAA / NANOSHEETS',2,1.78,0,2.9);explode(ns,0,1.15,0);
 const wire=group(world,'metal');for(let k=0;k<3;k++){const layer=group(wire);for(let i=0;i<5;i++){if(k%2)box(layer,.075,.08,2.7,.25+i*.7,1.5+k*.3,0,p.copper);else box(layer,3,.08,.075,1.65,1.5+k*.3,-1.2+i*.6,p.copper)}explode(layer,0,2+k*.65,0)}textLabel(wire,'BEOL / INTERCONNECT',2,2.5,-1.4,3);explode(wire,0,0,0);return [8.8,8,10.7,0,1.1,0]}
 function lithography(){floor(10);const tool=group(world,'lithography');box(tool,3.1,.55,3.6,0,.2,0,p.case);for(const x of [-1.45,1.45])for(const z of [-1.6,1.6])box(tool,.12,3.4,.12,x,1.9,z,p.metal);const roof=group(world,'lithography');box(roof,3.15,.16,3.65,0,3.65,0,p.frame);explode(roof,0,2,-2.2);explode(tool,0,.2,-.2);
 const w=group(world,'resist');wafer(w,0,.62,0,1.28);cylinder(w,1.28,.017,0,.663,0,p.violet);textLabel(w,'PHOTORESIST / WAFER',0,.9,1.8,3);explode(w,0,.6,0);
 const mask=group(world,'mask');box(mask,1.6,.065,1.6,0,2.8,0,p.violet);for(let i=0;i<6;i++)box(mask,.05,.009,1.25,-.65+i*.25,2.84,0,p.gold);textLabel(mask,'RETICLE',0,3.13,0,1.8);explode(mask,0,1.5,0);
 const light=group(world,'euv');for(let j=0;j<3;j++){cylinder(light,.5,.12,0,1.25+j*.42,0,p.metal);ring(light,0,1.32+j*.42,0,.47,p.blue)}pipe(light,[[0,2.75,0],[.1,2.2,.05],[-.12,1.7,0],[0,.72,0]],p.teal,.022);textLabel(light,'PATTERN TRANSFER',2.3,2.1,0,2.8);explode(light,2.1,.3,0);
 const track=group(world,'track');box(track,1.6,1.1,2,-3,.55,0,p.case);for(let j=0;j<3;j++)cylinder(track,.32,.06,-3,1.16,-.65+j*.65,p.copper);textLabel(track,'COAT / DEVELOP',-3,1.6,0,2.35);explode(track,-.8,0,0);return [7.8,6.6,9.9,-.5,1.6,0]}
 function chamber(){floor(11);const ch=group(world,'etch');cylinder(ch,1.7,.18,0,.3,0,p.metal);cylinder(ch,1.7,1.25,0,1,0,p.case,true);wafer(ch,0,.69,0,1.24);textLabel(ch,'PROCESS CHAMBER',0,.35,2.1,2.8);
 const lid=group(world,'chamberparts');cylinder(lid,1.77,.22,0,1.74,0,p.metal);for(let i=0;i<8;i++)box(lid,.09,.055,.09,Math.sin(i*Math.PI/4)*1.5,1.88,Math.cos(i*Math.PI/4)*1.5,p.gold);explode(lid,0,2.5,0);textLabel(lid,'CHAMBER PARTS',0,2.1,0,2.5);
 const dep=group(world,'ald');cylinder(dep,1.08,.07,0,1.47,0,p.gold);for(let i=0;i<30;i++){const a=i*2.4,r=Math.sqrt(i/30)*.9;cylinder(dep,.035,.012,Math.cos(a)*r,1.515,Math.sin(a)*r,p.ink)}explode(dep,0,1.1,0);textLabel(dep,'DEPOSITION / ETCH',0,1.7,-1.4,2.7);
 const gas=group(world,'specialgas');for(let i=0;i<3;i++){cylinder(gas,.32,1.65,-3+i*.67,.85,-.6,paletteGas(i));cylinder(gas,.09,.2,-3+i*.67,1.77,-.6,p.gold)}pipe(gas,[[-2.3,1.85,-.6],[-2.3,2.3,-.6],[-.5,2.3,-.6],[-.5,1.74,-.6]],p.teal,.05);textLabel(gas,'PROCESS GASES',-2.5,2.7,-.6,2.4);explode(gas,-1.1,0,0);
 const pump=group(world,'vacuum');box(pump,1.25,.8,.8,2.8,.45,.2,p.metal);for(let i=0;i<8;i++)box(pump,.06,.86,.85,2.35+i*.12,.45,.2,p.case);pipe(pump,[[1.5,.5,.4],[2.1,.5,.4],[2.1,.5,.2],[2.5,.5,.2]],p.blue,.12);textLabel(pump,'VACUUM',2.8,1.2,.2,1.8);explode(pump,1,0,.6);return [8.2,7,10.2,0,1.1,0]}
 function paletteGas(i){return [p.teal,p.blue,p.violet][i]}
 function polishing(){floor(10);const unit=group(world,'cmp');box(unit,4.2,.65,3.7,0,.28,0,p.case);cylinder(unit,1.58,.17,0,.72,0,p.metal);textLabel(unit,'CMP / PLANARIZATION',0,.45,2.2,3.1);
 const pad=group(world,'pad');cylinder(pad,1.53,.09,0,.86,0,p.copper);for(let i=1;i<7;i++)ring(pad,0,.915,0,i*.22,p.gold);textLabel(pad,'PAD + CONDITIONER',0,1.1,1.7,2.9);const arm=group(pad);box(arm,1.8,.15,.2,-1.6,1.13,-.6,p.metal);cylinder(arm,.27,.12,-.85,1.0,-.6,p.gold);explode(pad,0,.65,0);
 const w=group(world,'raw');wafer(w,.38,1.02,0,.67);cylinder(w,.7,.28,.38,1.2,0,p.case);box(w,.3,1,.3,.38,1.7,0,p.metal);textLabel(w,'WAFER CARRIER',.38,2.4,0,2.4);explode(w,0,2,0);
 const sl=group(world,'slurry');cylinder(sl,.44,1.3,-3,.65,-.7,p.teal);pipe(sl,[[-3,1.32,-.7],[-2.3,1.8,-.7],[-1,1.8,-.7],[0,1.15,-.7]],p.teal,.044);textLabel(sl,'SLURRY',-3,1.75,-.7,1.8);explode(sl,-.8,.2,0);
 const clean=group(world,'wetclean');box(clean,1.15,1.3,1.8,3,.65,0,p.case);for(let i=0;i<4;i++)box(clean,.75,.07,1.4,3,.9+i*.12,0,p.blue);textLabel(clean,'POST-CMP CLEAN',3,1.85,0,2.5);explode(clean,.6,.2,0);return [8.3,6.7,10.2,0,1.2,0]}
 function facility(){floor(13);const shell=group(world,'cleanroom');for(let j=0;j<3;j++){const g=group(shell);box(g,7.4,.2,5.8,0,.22+j*1.85,0,p.case);for(const x of [-3.5,3.5])for(const z of [-2.7,2.7])box(g,.14,1.8,.14,x,1.15+j*1.85,z,p.metal);explode(g,0,j*.5,0)}textLabel(shell,'CLEANROOM / HVAC',0,4.7,-2.6,3.2);
 const mach=group(world,'lithography');for(let i=0;i<3;i++)for(let j=0;j<2;j++){box(mach,1.6,.85,1.45,-2.3+i*2.3,2.61,-1.4+j*2.8,p.frame);box(mach,.6,.26,.07,-2.3+i*2.3,2.77,-.63+j*2.8,p.teal)}explode(mach,0,.5,0);
 const w=group(world,'upw');for(let i=0;i<4;i++)cylinder(w,.38,1.2,-2.5+i*.85,.9,1.2,p.blue);pipe(w,[[-2.5,1.55,1.2],[.1,1.55,1.2],[.1,2.3,1.2]],p.blue,.045);textLabel(w,'ULTRAPURE WATER',-1.4,1.75,2.7,2.9);explode(w,-.8,0,1.1);
 const pow=group(world,'electricity');box(pow,1.3,1.2,1.2,2.3,.9,1.3,p.gold);for(let i=0;i<5;i++)box(pow,.95,.03,.05,2.3,.52+i*.2,1.94,p.frame);textLabel(pow,'UTILITIES',2.3,1.8,2.7,2);explode(pow,1,0,1.2);
 const ab=group(world,'abatement');for(let i=0;i<3;i++){cylinder(ab,.42,1.6,4.7,.85,-2+i*1.2,p.metal);pipe(ab,[[3,.9,-2+i*1.2],[4.7,.9,-2+i*1.2]],p.copper,.075)}textLabel(ab,'ABATEMENT',4.7,2.25,-.5,2.4);explode(ab,1,0,0);
 const am=group(world,'amhs');box(am,6.9,.1,.14,0,3.55,.3,p.teal);for(let i=0;i<3;i++)box(am,.5,.46,.5,-2+i*2,3.3,.3,p.violet);textLabel(am,'AMHS',0,4,.3,1.5);explode(am,0,1.3,0);return [11.6,8.2,13.8,.5,2,0]}
 function costpackage(){floor(9);const sub=group(world,'package');box(sub,4.6,.22,3.6,0,.36,0,p.gold);for(let j=0;j<4;j++)box(sub,4.61,.02,3.61,0,.29+j*.05,0xb37e44);textLabel(sub,'SUBSTRATE / MATERIALS',0,.65,2,3.3);
 const bond=group(world,'bonding');box(bond,4,.12,3,0,.62,0,p.violet);for(const x of [-.9,.9]){box(bond,1.45,.12,1.5,x,.78,0,p.green);for(let i=0;i<5;i++)for(let j=0;j<5;j++)cylinder(bond,.035,.04,x-.56+i*.27,.685,-.55+j*.27,p.metal)}textLabel(bond,'INTERPOSER / BONDING',0,1.1,-1.7,3.4);explode(bond,0,1.6,0);
 const probe=group(world,'probe');box(probe,3,.14,2.2,0,1.6,0,p.board);for(let i=0;i<15;i++)box(probe,.025,.24,.025,-1.2+(i%5)*.6,1.42,-.7+Math.floor(i/5)*.7,p.gold);textLabel(probe,'TEST INTERFACE',0,1.95,0,2.5);explode(probe,0,2.6,0);
 const dice=group(world,'dicing');box(dice,.15,1.1,1.1,-3.0,.75,0,p.metal);textLabel(dice,'THIN / SINGULATE',-3,1.65,0,2.55);explode(dice,-.3,.4,0);return [7.7,6.5,9.4,0,1.2,0]}
 return {fabflow,lithography,chamber,polishing,facility,costpackage};
}
